//! Render the browser ABI limit table in `docs/browser.md` from the `MAX_*` constants of
//! `crates/vm-wasm/src/lib.rs`, so the shipped page cannot drift from the code.
use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

const PAGE: &str = "docs/browser.md";
const SOURCE: &str = "crates/vm-wasm/src/lib.rs";
const BEGIN: &str =
    "<!-- browser-limits:begin (generated by `cargo xtask browser-docs --write`) -->";
const END: &str = "<!-- browser-limits:end -->";

/// What each limit is called in the page, the unit of its value, and what happens past it.
const ROWS: &[(&str, &str, &str, &str)] = &[
    (
        "Artifact (`.gub`) size; also the largest single input buffer",
        "MAX_ARTIFACT_BYTES",
        "bytes",
        "`E_ABI_LIMIT`",
    ),
    (
        "Request JSON",
        "MAX_REQUEST_BYTES",
        "bytes",
        "`E_ABI_LIMIT`",
    ),
    (
        "Response JSON",
        "MAX_RESPONSE_BYTES",
        "bytes",
        "`E_ABI_LIMIT`",
    ),
    (
        "Execution steps (a request may lower this, never raise it)",
        "MAX_BROWSER_STEPS",
        "steps",
        "`E_ABI_LIMIT` for a request above it, `R_STEP_LIMIT` when a run reaches it",
    ),
    (
        "Captured output (a request may lower this, never raise it)",
        "MAX_OUTPUT_BYTES",
        "bytes",
        "`E_ABI_LIMIT` for a request above it, `R_OUTPUT_LIMIT` when a run reaches it",
    ),
    (
        "Error text kept by the legacy getters",
        "MAX_ERROR_BYTES",
        "bytes",
        "none; the text is cut at a character boundary",
    ),
    (
        "VM allocation per run",
        "MAX_BROWSER_ALLOCATION_BYTES",
        "bytes",
        "`R_ALLOCATION_LIMIT`",
    ),
    (
        "Live caller input buffers",
        "MAX_LIVE_INPUTS",
        "buffers",
        "`allocate_input` returns 0",
    ),
    (
        "Live caller input bytes in total",
        "MAX_LIVE_INPUT_BYTES",
        "bytes",
        "`allocate_input` returns 0",
    ),
    (
        "Recursive wire depth",
        "MAX_WIRE_DEPTH",
        "levels",
        "`E_ABI_LIMIT`",
    ),
    (
        "Wire value nodes",
        "MAX_WIRE_NODES",
        "nodes",
        "`E_ABI_LIMIT`",
    ),
    (
        "Items in one collection",
        "MAX_WIRE_COLLECTION_ITEMS",
        "items",
        "`E_ABI_LIMIT`",
    ),
    (
        "One text or bytes value",
        "MAX_WIRE_VALUE_BYTES",
        "bytes",
        "`E_ABI_LIMIT`",
    ),
    (
        "Integer digits",
        "MAX_WIRE_INTEGER_DIGITS",
        "digits",
        "`E_ABI_LIMIT`",
    ),
];

fn read(root: &Path, path: &str) -> Result<String, String> {
    fs::read_to_string(root.join(path)).map_err(|error| format!("read {path}: {error}"))
}

/// Evaluate `a * b * 4_096 * OTHER` style constant expressions.
fn evaluate(expression: &str, known: &BTreeMap<String, u128>) -> Result<u128, String> {
    let mut product = 1_u128;
    for factor in expression.split('*') {
        let factor = factor.trim();
        let number = if let Some(value) = known.get(factor) {
            *value
        } else {
            factor
                .replace('_', "")
                .trim_end_matches("u32")
                .trim_end_matches("usize")
                .parse::<u128>()
                .map_err(|_| format!("cannot evaluate `{expression}`"))?
        };
        product *= number;
    }
    Ok(product)
}

fn constants(source: &str) -> Result<BTreeMap<String, u128>, String> {
    let mut found = BTreeMap::new();
    for line in source.lines() {
        let line = line.trim();
        let Some(rest) = line.strip_prefix("pub const MAX_") else {
            continue;
        };
        let Some((name, rest)) = rest.split_once(':') else {
            continue;
        };
        let Some((_, expression)) = rest.split_once('=') else {
            continue;
        };
        let expression = expression.trim().trim_end_matches(';');
        let value = evaluate(expression, &found)?;
        found.insert(format!("MAX_{name}"), value);
    }
    Ok(found)
}

fn group(value: u128) -> String {
    let digits = value.to_string();
    let mut out = String::new();
    for (index, digit) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index).is_multiple_of(3) {
            out.push(',');
        }
        out.push(digit);
    }
    out
}

fn table(source: &str) -> Result<String, String> {
    let known = constants(source)?;
    let mut out =
        String::from("| Limit | Constant | Value | Past the limit |\n|---|---|---:|---|\n");
    for (label, constant, unit, code) in ROWS {
        let value = known
            .get(*constant)
            .ok_or_else(|| format!("{SOURCE} has no `pub const {constant}`"))?;
        out.push_str(&format!(
            "| {label} | `{constant}` | {} {unit} | {code} |\n",
            group(*value)
        ));
    }
    Ok(out)
}

fn render(root: &Path) -> Result<String, String> {
    let page = read(root, PAGE)?;
    let begin = page
        .find(BEGIN)
        .ok_or_else(|| format!("{PAGE} is missing the line `{BEGIN}`"))?;
    let end = page
        .find(END)
        .ok_or_else(|| format!("{PAGE} is missing the line `{END}`"))?;
    if end < begin {
        return Err(format!("{PAGE}: the limit table markers are out of order"));
    }
    let table = table(&read(root, SOURCE)?)?;
    Ok(format!(
        "{}{BEGIN}\n\n{table}\n{}",
        &page[..begin],
        &page[end..]
    ))
}

pub fn check(root: &Path) -> Result<(), String> {
    if read(root, PAGE)? != render(root)? {
        return Err(format!(
            "{PAGE} is out of date; run `cargo xtask browser-docs --write`"
        ));
    }
    Ok(())
}

pub fn write(root: &Path) -> Result<(), String> {
    fs::write(root.join(PAGE), render(root)?).map_err(|error| format!("write {PAGE}: {error}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evaluates_the_constant_forms_in_the_source() {
        let known = constants(
            "pub const MAX_A_BYTES: usize = 1024 * 1024;\npub const MAX_B: u32 = 10_000;\npub const MAX_C: usize = MAX_A_BYTES * 2;\n",
        )
        .unwrap();
        assert_eq!(known["MAX_A_BYTES"], 1_048_576);
        assert_eq!(known["MAX_B"], 10_000);
        assert_eq!(known["MAX_C"], 2_097_152);
        assert_eq!(group(1_048_576), "1,048,576");
    }
}
